pageStyle:
.row.section-header { display: none; }

.blurb > .logo > img { width: 70px; } 

.mini-card-video video {
  width: -webkit-fill-available;
  display: block;
  width: 365px;
}

.dcc > img { width: 74.13px; }

.pov > div.img > img { width: 50px; }

#byor_single_search {
    border: 2px solid #ff6600;
    padding: 20px;
}

.mdkp-body{
background:white !important;
min-height:100px;
}
.mdkp-body.front-page {
    padding-bottom: 0px;
    display: none;
}
.fp-intro-logo{
min-width:0;
height:70px;
}
.fp-intro-section {
    flex-direction: column;
    align-items: center;
    margin: 30px 0 0;
}
.fp-intro-divider {
display:none;
}
.fp-intro-blurb {
    min-width: calc(50% - 20.5px);
    text-align: center;
    display: flex;
    align-items: center;
    justify-content: center;
}
.fp-intro-blurb-text {
    color: #ff6600;
    text-transform: uppercase;
    font-size: 14px;
    font-weight: bold;
    letter-spacing: 1px;
}
.page-description-content{
    width: 100%;
    display: flex;
    flex-direction: column;
}

.map-title2 {
margin-bottom: 20px !important;
}


.mdkp-body.flex-body.front-page {
    overflow-x: visible;
	flex: none;
}
.mdkp-body.flex-body:has(.kc-wrap){
	padding-top: 0;
}
.fp-search-section {
    margin: 50px 0 20px;
}
.multi-section.wrapper-section-0:has(.col-md-12.wrapper-section-0:empty){
	display: none;
}
#byor_single_search {
    border: 2px solid #ff6600;
    padding: 20px;
}
.col-md-12:has(.kc-wrap) {
    padding: 0;
}
.kc-hero {
    background: #f7f6f6;
}
.blurb {
    display: flex;
    align-items: center;
	justify-content: space-between;
	padding: 30px 0px 40px;
    gap: 20px;
}
.blurb div {
	font-size: 16px;
    color: #7c7c7c;
	font-weight: bold;
}
.blurb span {
	color: inherit;
	font-weight: normal;
}
.blurb span.highlight{
	color: #f26822;
	font-weight: bold;
}
.blurb .logo {
    width: 70px;
    flex: unset;
}
.blurb .logo img {
    width: -webkit-fill-available;
    object-fit: contain;
}
.map-bg{
	 /*background: #f7f6f6;*/
	 display: flex;
    flex-direction: column;
    align-items: center;
	/*box-shadow: inset 0px 10px 10px -10px #00000010, inset 0px -10px 10px -10px #00000010;*/
}
.map-title {
    margin: 20px 0 0 0;
    font-size: 12px;
	margin: 0 auto;
    position: absolute;
    left: 0;
    padding: 0 20px;
    width: 250px;
    margin-top: 83px;
    display: flex;
    flex-direction: column;
    
	color: #7c7c7c;
	z-index: 10;
}
.map-title.boxed{
	background: white;
    padding: 20px;
    border-radius: 0 10px 10px 0;
	margin-top: 0;
}
.map-title>span{
	color: #ff6600;
	text-transform: uppercase;
	font-weight: bold;
    letter-spacing: 1px;
	display: contents;
}
.map-title2 {
    color: #7c7c7c;
    width: 100%;
    margin: 0 0 10px 0;
	text-align: center;
}
.map-title2>span {
    text-transform: uppercase;
    font-size: 14px;
    font-weight: bold;
    letter-spacing: 1px;
    color: #ff6600;
	display: flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
}
.map-bg .map-title2>span {
    font-size: 16px;
}
.how {
    font-size: 11px;
    text-transform: none;
    color: black;
    letter-spacing: normal;
    font-weight: normal;
    display: flex;
    gap: 5px;
    align-items: center;
    cursor: pointer;
	margin: 5px 0 0;
	width: fit-content;
}
.btn-icon {
    display: flex !important;
    border: 1px solid black !important;
    font-weight: 600;
    height: 12px;
    width: 12px;
    border-radius: 50%;
    line-height: 20px;
    align-items: center;
    justify-content: center;
    font-size: 9px;
	color: black !important;
	cursor: pointer;
}
.map-pov-message{
	font-size: 12px;
    background: #ff6600;
	color:white;
    padding: 3px 10px;
    border-radius: 5px;
    position: absolute;
	z-index: 10;
	box-shadow: 1px 1px 2px 0 #00000050;
	display: none;
}
.map {
	display: flex;
	flex-direction: column;
	gap: 0px;
	width: 830px;
	margin: 0 auto;
	padding: 0px 0 0px 0;
}
.povs,
.dccs,
.omics,
.entities{
	display: flex;
	justify-content: center;
	gap: 10px;
	position: relative;
}
.povs{
	gap: 30px;
	justify-content: space-between;
}
.pov {
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: space-between;
	gap: 0px;

	/*width: 170px;
	width: 50px;
	aspect-ratio: 1;*/

	background: none;
	cursor: pointer;
	
	text-align: center;   
	filter: brightness(0);
}
.pov:hover {
	background: none !important;
}
.pov.selected {
	filter: none;
	/*border-bottom: solid 3px #ff6600;*/
}
.pov span {
	background: none;
	padding: 3px 0 1px 0;
	flex: 1 1 auto;
	color: black;
	display: flex;
	align-items: center;
	justify-content: center;
	pointer-events: none;
	text-transform: uppercase;
	font-size: 11px;
	font-weight: bold;
	letter-spacing: 1px;
}
.pov span{
	border-bottom: 1px solid transparent;
}
.pov:hover span,
.pov.selected span {
	background: none;
	color: #ff6600;
}
.pov img {
	width: -webkit-fill-available;
	height: auto;
	aspect-ratio: 1;
	object-fit: contain;
	pointer-events: none;
	padding: 5px;
}
.povs .img {
    width: 50px;
    height: 50px;
	pointer-events: none;
	border-radius: 5px;
}

.dccs{
	margin: 0 0 15px -25% !important;
    width: 150% !important;
	gap: 0;
    align-items: center;
	/*margin: 0 0 15px 0;
    width: 100%;*/
}
.dcc {
	display: flex;
	flex: 1 1 auto;
	align-items: center;
	justify-content: center; 

	width: 50px;
	aspect-ratio: 1;

	background: none;
	border-top: 3px solid transparent;
	cursor: default;
	   
	transition: .2s all ease-out;
}
.dcc:hover {
	background: none !important;
	border-top: solid 3px #ff6600;
}
.dcc img {
	width: -webkit-fill-available;
	height: auto;
	object-fit: contain;
	margin: 0 10px;
	pointer-events: none;
	mix-blend-mode: darken;
}
.dcc-separator {
    background: #ccc;
    width: 0.5px;
    height: 50px;
    margin: 0 5px;
}
.dcc-separator:last-child {
    display: none;
}
.dcc.onA, .dcc.on2A, .dcc.on3A{
	border-top: solid 1px transparent;
	padding-top: 2px;
}
.dcc.on{
	border-top:3px solid #ff6600 !important;
	/*background: #f0f0f0;
	outline: 5px solid white;
	outline-offset: -5px;*/
}
.dcc.on2{
	/*background: #f0f0f0;
	outline: 2.5px solid #e6e6e6;*/
}
.dcc.on3{
	/*background: #f0f0f0;
	outline: 10px solid #e6e6e6;*/
}
.dccs.active .dcc:hover{
	border-top:3px solid #ff6600;
}

.omics {
	display: flex;
	gap: 0;
	align-items: center;
	justify-content: center; 

	margin: 0 0 20px 0;

	background: none;
	cursor: default;

	gap: 5px;
}
.omic{
	display: flex;
	flex: 1 1 auto;
	align-items: center;
	justify-content: center;

	aspect-ratio: unset;
	height: 20px;
	
	text-transform: uppercase;
	font-size: 11px;
	padding: 0 5px;
	letter-spacing: 1px;
	font-weight: 600;

	background: #ddd;
	filter: grayscale(1);

	cursor: default;
	transition: .2s all linear;
}
.omic:hover{
	background: #ff802c !important;
	filter: none;
	color: white;
}
.omics.active .omic{
	min-width: 100px;
	/*flex: 0 0 auto;*/
	overflow: hidden;
}
.omic span,
.entity span{
	pointer-events: none;
}
.omics.active .omic.on{
	/*flex: 1 1 auto;*/
	background: #ff802c;
	filter: none;
	color: white;
}

.entities{
	gap: 0px;
}
.entity {
	display: flex;
	flex: 1 1 auto;
	align-items: center;
	justify-content: center; 
	
	width: auto;
	height: 20px;

	background: none;   
	/*border-bottom: 3px solid transparent;*/
	cursor: default;

	text-transform: uppercase;
	font-size: 11px;
	font-weight: bold;
	letter-spacing: .5px;
}
.entity:hover,
.entity.on{
	/*background:#ff6600;*/
	color:#ff6600;
	/*border-bottom: 3px solid #ff6600;*/
}

.line2 {
	font-size: 14px;
	height: 100px;
	display: flex;
	align-items: center;
	justify-content: center;
	width: 150%;
    padding: 0 300px;
    text-align: center;
    margin: 0 0 0 -25%;
	text-align: center;
	transition: .2s all ease-out;
	z-index: 2;
	position: relative;
	background:transparent;
}
.line2.open:has(.line2info:not(:empty)){
	background:#f7f6f695;
	backdrop-filter: blur(2px);
}
.hidden{
	display:none;
}

.map-label {
	position: absolute;
    right: 50%;
    transform: translateX(50%);
    line-height: 12px;
    width: 100vw;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    text-align: right;
    font-size: 11px;
    height: 100%;
